fn count_under_over(cutoff: Int, samples: &Vec<Int>) -> Vec<Int> {
    let mut under = 0
    let mut over = 0
    for x in samples {
        if x < cutoff {
            under = under + 1
        } else {
            over = over + 1
        }
    }
    vec(under, over)
}

